#include "ItemIdentityRuntime.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::items {bool ItemIdentityRuntime::add(ItemState i,std::string&w){if(!i.id||!i.material||!i.quantity){w="invalid item";return false;}i.condition=std::clamp(std::isfinite(i.condition)?i.condition:0.0,0.0,1.0);if(!items_.emplace(i.id,std::move(i)).second){w="duplicate item";return false;}return true;}bool ItemIdentityRuntime::promote(StableId id,IdentityTier t,std::string&w){auto i=items_.find(id);if(i==items_.end()){w="unknown item";return false;}if(std::uint8_t(t)<std::uint8_t(i->second.tier)){w="demotion requires reaggregation";return false;}i->second.tier=t;return true;}bool ItemIdentityRuntime::canReaggregate(StableId id)const{auto i=items_.find(id);if(i==items_.end())return false;auto&x=i->second;return !x.owner&&!x.reservation&&!x.modified&&!x.evidence&&!x.historySignificant&&x.tier!=IdentityTier::Artifact;}bool ItemIdentityRuntime::transferOwnership(StableId id,StableId owner,ContentId reason,std::string&w){auto i=items_.find(id);if(i==items_.end()){w="unknown item";return false;}i->second.owner=owner;auto&c=claims_[id];c={id,owner,reason,c.revision+1};if(owner&&std::uint8_t(i->second.tier)<std::uint8_t(IdentityTier::NamedOwned))i->second.tier=IdentityTier::NamedOwned;return true;}std::optional<ItemState>ItemIdentityRuntime::get(StableId id)const{auto i=items_.find(id);if(i==items_.end())return std::nullopt;return i->second;}}
